import {PETS,addMaterial} from './economy.mjs?v=0.6';
import {gatherBoost,gatherSeconds} from './pet-data.mjs?v=0.6';
export const CAPACITIES=[[50,75],[75,150],[150,250],[250,400],[400,700]];
export function rollCapacity(grade,rng=Math.random){const [lo,hi]=CAPACITIES[grade];return lo+Math.floor(Math.min(.999999999,rng())*(hi-lo+1));}
export function rollHarvestGrade(grade,rng=Math.random){if(grade<3)return grade;const r=rng();return grade===3?(r<.2?3:2):(r<.2?4:r<.5?3:2);}
export function harvestDuration(s,kind){return gatherSeconds(gatherBoost(s,kind,PETS));}
export function initializeNode(s,n,rng){s.harvest??={};const key=s.map+':'+n.id;let data=s.harvest[key];if(!data){const capacity=rollCapacity(n.grade,rng);data=s.harvest[key]={capacity,remaining:capacity,readyAt:0};}return {...n,...data,store:data,cd:Math.max(0,data.readyAt-s.playTime)};}
export function tickNodes(game,dt){for(const n of game.nodes){n.cd=Math.max(0,n.cd-dt);if(n.remaining===0&&n.cd===0){const capacity=rollCapacity(n.grade,game.random);Object.assign(n,{capacity,remaining:capacity});Object.assign(n.store,{capacity,remaining:capacity,readyAt:0});}}}
export function harvestNode(game,n){if(n.cd>0||n.remaining<=0)return false;const s=game.s,grade=rollHarvestGrade(n.grade,game.random),trade=game.random()<.2;const kinds=[n.type,{ore:'steel',herb:'cloth',energy:'gem'}[n.type],...(n.type==='energy'?['feather']:[])];for(const k of kinds)addMaterial(s,k,grade,1,trade);n.remaining--;n.store.remaining=n.remaining;if(n.remaining===0){n.cd=60;n.store.readyAt=s.playTime+60;}if(s.map!=='van')s.regions[s.map][n.type]++;s.counts[{ore:'mined',herb:'gathered',energy:'meditated'}[n.type]]++;game.addXP(8);game.emit('gather',{x:n.x,z:n.z,kind:n.type,grade,trade,remaining:n.remaining});return {grade,trade};}
export function validateHarvest(s){if(s.harvest===undefined)return;if(!s.harvest||Array.isArray(s.harvest)||Object.keys(s.harvest).length>300||Object.entries(s.harvest).some(([key,v])=>! /^(van|truc|bang|hoa|thien):node\d+$/.test(key)||!v||!Number.isInteger(v.capacity)||v.capacity<50||v.capacity>700||!Number.isInteger(v.remaining)||v.remaining<0||v.remaining>v.capacity||!Number.isFinite(v.readyAt)||v.readyAt<0))throw Error('Trữ lượng mỏ không hợp lệ');}
